 29→/// Maximum total execution attempts per step (auto-retries + manual retries).
 30→/// Prevents infinite loops when the recovery prompt always returns "retry"
 31→/// (e.g., in test environments with MockUI).
 32→const MAX_STEP_ATTEMPTS: u32 = 100;
