 31→impl CommandResult {
 32→    /// Create a success result.
 33→    pub fn success(stdout: String, stderr: String, duration: Duration) -> Self {
 34→        Self {
 35→            exit_code: Some(0),
 36→            stdout,
 37→            stderr,
 38→            duration,
 39→            success: true,
 40→        }
 41→    }
