107→          settings:
108→            output: verbose
109→            logging: true
110→          steps:
111→            - name: first
112→            - name: second
113→        "#;
114→        let parsed: serde_yaml::Value = serde_yaml::from_str(yaml).unwrap();
115→        assert_eq!(parsed["settings"]["output"], "verbose");
116→        assert_eq!(parsed["steps"][0]["name"], "first");
117→    }
118→}
