 845→    #[test]
 846→    fn resolve_environment_fallback_when_no_config() {
 847→        let temp = TempDir::new().unwrap();
 848→        let args = RunArgs::default();
 849→        let cmd = RunCommand::new(temp.path(), args);
 850→
 851→        let config = crate::config::BivvyConfig::default();
 852→        let resolved = cmd.resolve_environment(&config);
 853→
 854→        // Without flag or config default, environment is either auto-detected
 855→        // (e.g. "ci" in CI) or falls back to "development"
 856→        match &resolved.source {
 857→            crate::environment::resolver::EnvironmentSource::Fallback => {
 858→                assert_eq!(resolved.name, "development");
 859→            }
 860→            crate::environment::resolver::EnvironmentSource::AutoDetected(_) => {
